#!/usr/bin/env bash
# Pass or fail check for the one-hour Gemma test. It prints one line per check
# and exits non-zero unless every check passes. Do not edit this file.
set -u
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT" || exit 99
# shellcheck disable=SC1091
source "$ROOT/scripts/env.sh"

BASE="build/s1-base"
WASM="target/near/vault/vault.wasm"
TEST_NAME="vault_rejects_every_caller_but_parent"
LOG="$(mktemp -t vault-check)"
fails=0

pass() { printf 'PASS %s\n' "$1"; }
fail() { printf 'FAIL %s: %s\n' "$1" "$2"; fails=$((fails + 1)); }

# 1. Rules, plan, docs and this script are unchanged.
if git diff --quiet "$BASE" -- scripts AGENTS.md PLAN.md docs rust-toolchain.toml tests Cargo.toml Cargo.lock contracts/vault/Cargo.toml contracts/test-token \
  && [ -z "$(git status --porcelain -- scripts AGENTS.md PLAN.md docs rust-toolchain.toml tests Cargo.toml Cargo.lock contracts/vault/Cargo.toml contracts/test-token)" ]; then
  pass "protected files unchanged"
else
  fail "protected files unchanged" "only contracts/vault/src/lib.rs may change. Restore the other files with git checkout."
fi

# 2. No tool-call text leaked into file names or contents.
bad="$(python3 -I - <<'PY'
import os
tokens = ('<|tool_call', '<tool_call|>', '<|channel>', '<channel|>', '<|"|>', '<|tool_response')
skip_dirs = {'.git', 'target', 'node_modules'}
skip_files = {'PLAN.md', 'scripts/vault-check.sh'}
found = []
for folder, subs, files in os.walk('.'):
    subs[:] = [s for s in subs if s not in skip_dirs and not os.path.join(folder, s).startswith('./docs/sources')]
    for name in files + subs:
        if any(c in name for c in '`<>{}|\n'):
            found.append('name: ' + repr(os.path.join(folder, name))[:100])
    for name in files:
        path = os.path.relpath(os.path.join(folder, name), '.')
        if path in skip_files or os.path.getsize(path) > 2_000_000:
            continue
        try:
            text = open(path, encoding='utf-8', errors='ignore').read()
        except OSError:
            continue
        if any(t in text for t in tokens):
            found.append('content: ' + path)
print('\n'.join(found[:10]))
PY
)"
if [ -z "$bad" ]; then
  pass "no corrupted file names or contents"
else
  fail "no corrupted file names or contents" "delete or rewrite these: $bad"
fi

# 3. The vault crate exists and belongs to the workspace.
if [ -f contracts/vault/Cargo.toml ] && [ -f contracts/vault/src/lib.rs ] && grep -q '"contracts/vault"' Cargo.toml; then
  pass "vault crate is in the workspace"
else
  fail "vault crate is in the workspace" "need contracts/vault/Cargo.toml, contracts/vault/src/lib.rs and \"contracts/vault\" in the root Cargo.toml members"
fi

# 4. The contract builds with the plan's command.
rm -f "$WASM"
if [ -f contracts/vault/Cargo.toml ] \
  && cargo build --locked -p vault --target wasm32-unknown-unknown --release >"$LOG" 2>&1 \
  && mkdir -p target/near/vault \
  && cp target/wasm32-unknown-unknown/release/vault.wasm "$WASM" \
  && [ -s "$WASM" ]; then
  pass "vault builds to $WASM"
else
  fail "vault builds to $WASM" "build failed. Last lines:"
  tail -25 "$LOG"
fi

# 5. The wasm exports the four methods and is under the size limit.
if [ -s "$WASM" ]; then
  exports="$(python3 -I - "$WASM" <<'PY'
import sys
data = open(sys.argv[1], 'rb').read()
def leb(i):
    result = shift = 0
    while True:
        b = data[i]; i += 1
        result |= (b & 0x7f) << shift
        shift += 7
        if not b & 0x80:
            return result, i
i, names = 8, []
while i < len(data):
    kind = data[i]; i += 1
    size, i = leb(i)
    if kind == 7:
        j = i
        count, j = leb(j)
        for _ in range(count):
            length, j = leb(j)
            names.append(data[j:j + length].decode()); j += length
            j += 1
            _, j = leb(j)
    i += size
print(' '.join(names))
PY
)"
  size="$(wc -c <"$WASM" | tr -d ' ')"
  missing=""
  for method in ft_send near_send ft_on_transfer nft_on_transfer; do
    case " $exports " in *" $method "*) ;; *) missing="$missing $method" ;; esac
  done
  if [ -n "$missing" ]; then
    fail "vault exports its four methods" "missing:$missing"
  else
    pass "vault exports its four methods"
  fi
  if [ "$size" -le 30720 ]; then
    pass "vault is $size bytes, within the 30 KB limit"
  else
    fail "vault size" "$size bytes is over the 30 KB limit"
  fi
else
  fail "vault exports its four methods" "no wasm to inspect"
fi

# 6. Every visible check passes.
cargo near build non-reproducible-wasm --locked --no-abi --manifest-path contracts/test-token/Cargo.toml >"$LOG" 2>&1 || { fail "test token builds" "$(tail -8 "$LOG")"; }
if cargo test --locked -p tests --test vault_spec -- --test-threads=3 >"$LOG" 2>&1 \
  && grep -q 'test result: ok. 9 passed' "$LOG"; then
  pass "all 9 checks in tests/tests/vault_spec.rs passed"
else
  fail "all 9 checks in tests/tests/vault_spec.rs passed" "details:"
  grep -E '^test .* (ok|FAILED)$|panicked|^error' "$LOG" | head -30
  tail -12 "$LOG"
fi

rm -f "$LOG"
if [ "$fails" -eq 0 ]; then
  echo "VAULT CHECK PASS"
  exit 0
fi
echo "VAULT CHECK FAIL: $fails checks failed"
exit 1
